import unittest
from probe import canonical_labels


class ProbeTests(unittest.TestCase):
    def test_normalize_and_deduplicate(self):
        self.assertEqual(canonical_labels([" Beta ", "ALPHA", "beta"]), ["alpha", "beta"])

    def test_empty(self):
        self.assertEqual(canonical_labels(["", "  "]), [])
        self.assertEqual(canonical_labels([]), [])

    def test_preserves_input(self):
        values = [" Z ", "a"]
        self.assertEqual(canonical_labels(values), ["a", "z"])
        self.assertEqual(values, [" Z ", "a"])

    def test_rejects_container(self):
        for value in (None, "abc", ("a",), {"a"}):
            with self.assertRaises(TypeError):
                canonical_labels(value)

    def test_rejects_element(self):
        for value in ([1], [True], [None], ["a", []]):
            with self.assertRaises(TypeError):
                canonical_labels(value)


if __name__ == "__main__":
    unittest.main()

